        ch = field[i]
        if ch == QUOTE:
            if quoted and i + 1 < length and field[i + 1] == QUOTE:
                i += 2
                continue
            quoted = not quoted
        elif ch == "=" and not quoted:
            return i
        i += 1
    return -1


