import random
from fractions import Fraction
from tally import allocate, intervals

random.seed(0)
for _ in range(5000):
    n = random.randint(1, 8)
    weights = [random.choice([0, 1, 2, 3, 5, 10, Fraction(1,3), 0.5]) for _ in range(n)]
    if sum(weights) == 0:
        continue
    total = random.randint(-200, 200)
    shares = allocate.apportion(total, weights)
    if sum(shares) != total:
        print("SUM FAIL", total, weights, shares)
        break
    # sign consistency
    if total >= 0 and any(s < 0 for s in shares):
        print("SIGN FAIL", total, weights, shares); break
    if total < 0 and any(s > 0 for s in shares):
        print("SIGN FAIL2", total, weights, shares); break
else:
    print("apportion random ok")

# merge properties: output sorted, non-touching, covers input
for _ in range(2000):
    ints = []
    for _ in range(random.randint(0, 8)):
        a = random.randint(-20, 20)
        b = random.randint(-20, 20)
        ints.append((a, b))
    try:
        merged = intervals.merge(ints)
    except ValueError:
        # ensure at least one start>end
        if not any(a > b for a, b in ints):
            print("unexpected merge error", ints); break
        continue
    if merged != sorted(merged):
        print("not sorted", ints, merged); break
    for (a, b), (c, d) in zip(merged, merged[1:]):
        if not (b < c):
            print("touch/overlap left", ints, merged); break
    # each nonempty input interval covered by some output interval
    for a, b in ints:
        if a == b:
            continue
        if not any(x <= a and b <= y for x, y in merged):
            print("not covered", ints, merged, (a, b)); break
    # total covered by merge equals sum of lengths
    if sum(b-a for a,b in merged) != intervals.total_covered(ints):
        print("total mismatch", ints, merged); break
else:
    print("merge random ok")
